// What a sandbox reported for one test case's execution: the actual output
// produced, time and memory used, and whether it crashed outright.
class ExecutionResult {
    String actualOutput;
    long timeUsedMillis;
    long memoryUsedMb;
    boolean crashed;

    ExecutionResult(String actualOutput, long timeUsedMillis, long memoryUsedMb, boolean crashed) {
        this.actualOutput = actualOutput;
        this.timeUsedMillis = timeUsedMillis;
        this.memoryUsedMb = memoryUsedMb;
        this.crashed = crashed;
    }
}

// Applies verdict logic to a sandbox's reported results: checks each test case
// in order for a crash, then a time limit violation, then a memory limit
// violation, and only then an output mismatch, stopping at the first failure.
class Judge {
    private final long timeLimitMillis;
    private final long memoryLimitMb;

    Judge(long timeLimitMillis, long memoryLimitMb) {
        this.timeLimitMillis = timeLimitMillis;
        this.memoryLimitMb = memoryLimitMb;
    }

    String evaluate(List<TestCase> testCases, List<ExecutionResult> results) {
        for (int i = 0; i < testCases.size(); i++) {
            TestCase testCase = testCases.get(i);
            ExecutionResult result = results.get(i);
            int caseNumber = i + 1; // 1-indexed, for a human-readable verdict message

            if (result.crashed) {
                return "RUNTIME_ERROR at test case " + caseNumber;
            }
            if (result.timeUsedMillis > timeLimitMillis) {
                return "TIME_LIMIT_EXCEEDED at test case " + caseNumber;
            }
            if (result.memoryUsedMb > memoryLimitMb) {
                return "MEMORY_LIMIT_EXCEEDED at test case " + caseNumber;
            }
            if (!result.actualOutput.equals(testCase.expectedOutput)) {
                return "WRONG_ANSWER at test case " + caseNumber;
            }
        }
        return "ACCEPTED"; // every test case passed every check
    }
}

