// produced, time and memory used, and whether it crashed outright.
struct ExecutionResult {
    string actualOutput;
    long timeUsedMillis;
    long memoryUsedMb;
    bool crashed;
};

// Applies verdict logic to a sandbox's reported results: checks each test case
// in order for a crash, then a time limit violation, then a memory limit
// violation, and only then an output mismatch, stopping at the first failure.
class Judge {
public:
    Judge(long timeLimitMillis, long memoryLimitMb)
        : timeLimitMillis(timeLimitMillis), memoryLimitMb(memoryLimitMb) {}

    string evaluate(const vector<TestCase>& testCases, const vector<ExecutionResult>& results) {
        for (size_t i = 0; i < testCases.size(); i++) {
            const TestCase& testCase = testCases[i];
            const ExecutionResult& result = results[i];
            int caseNumber = static_cast<int>(i) + 1; // 1-indexed, for a human-readable verdict message

            if (result.crashed) {
                return "RUNTIME_ERROR at test case " + to_string(caseNumber);
            }
            if (result.timeUsedMillis > timeLimitMillis) {
                return "TIME_LIMIT_EXCEEDED at test case " + to_string(caseNumber);
            }
            if (result.memoryUsedMb > memoryLimitMb) {
                return "MEMORY_LIMIT_EXCEEDED at test case " + to_string(caseNumber);
            }
            if (result.actualOutput != testCase.expectedOutput) {
                return "WRONG_ANSWER at test case " + to_string(caseNumber);
            }
        }
        return "ACCEPTED"; // every test case passed every check
    }

private:
    long timeLimitMillis;
    long memoryLimitMb;
};

int main() {
    long timeLimitMillis = 1000;
    long memoryLimitMb = 256;

    vector<TestCase> testCases = {
        {"[2,7,11,15], target=9", "[0,1]"},
        {"[3,2,4], target=6", "[1,2]"},
        {"[3,3], target=6", "[0,1]"}
    };

    Judge judge(timeLimitMillis, memoryLimitMb);

    // Submission A: correct output on every test case, well within resource limits.
    vector<ExecutionResult> resultsA = {
        {"[0,1]", 200, 20, false},
        {"[1,2]", 210, 20, false},
        {"[0,1]", 190, 20, false}
    };
    cout << "Submission A: " << judge.evaluate(testCases, resultsA) << endl;

    // Submission B: wrong output on the second test case; judging should stop there.
    vector<ExecutionResult> resultsB = {
        {"[0,1]", 200, 20, false},
        {"[1,3]", 210, 20, false},
        {"[0,1]", 190, 20, false}
    };
    cout << "Submission B: " << judge.evaluate(testCases, resultsB) << endl;

    // Submission C: exceeds the time limit on the very first test case.
    vector<ExecutionResult> resultsC = {
        {"[0,1]", 1500, 20, false},
        {"[1,2]", 210, 20, false},
        {"[0,1]", 190, 20, false}
    };
    cout << "Submission C: " << judge.evaluate(testCases, resultsC) << endl;

    // Submission D: exceeds the memory limit on the first test case.
    vector<ExecutionResult> resultsD = {
        {"[0,1]", 200, 300, false},
        {"[1,2]", 210, 20, false},
        {"[0,1]", 190, 20, false}
